39	// The sharing proof's handle checks (share_guard::Required::marks): after the statement at each line, a
40	// marker that rustc accepts only when the name's value (depth 0) or its items (depth 1) are handles.
41	pub fn share_marks(items: &mut [Item]) -> Vec<Diag> {
42	    let mut errs = vec![];
43	    for (line, var, depth) in crate::share_guard::required().marks {
44	        let msg = format!("{var} shares a list with another name, which the typed build would copy");
45	        let fix = "the dynamic build keeps Python's sharing".to_string();
46	        let hex: String = format!("{msg}\u{1}{fix}").bytes().map(|b| format!("{b:02x}")).collect();
47	        let kind = if depth == 0 { Expr::Bool(true) } else { Expr::Int(3) };
48	        let margs = vec![(None, Expr::Ident(var.clone())), (None, Expr::Str(vec![StrPart::Lit(hex)])), (None, kind)];
49	        let mark = Stmt::Expr { expr: Expr::Call("__shared".into(), margs, line), line };
50	        let placed = items.iter_mut().any(|it| match it {
51	            Item::Fn { body, .. } | Item::Test { body, .. } => place_mark(body, line, &var, &mark),
52	            _ => false,
53	        });
54	        if !placed {
55	            err_d(&mut errs, line, msg);
56	        }
57	    }
58	    errs
59	}
